                    for (let j = i; j < Math.min(rows.length, i + 5); j++) {
                        const L = rows[j] || [], li = { vid: hpFind(L, /вид опер/), sklad: hpFind(L, /^склад/), shpz: hpFind(L, /шифр затрат/) };
                        if (li.shpz < 0) continue;
                        const vr = j > i && hpN((rows[i] || [])[li.shpz]) !== null ? rows[i] : rows[j + 1] || [];
                        cur.vid = hpS(vr[li.vid]).replace(/\.0+$/, ''); cur.sklad = hpS(vr[li.sklad]).replace(/\.0+$/, ''); cur.shpz = hpS(vr[li.shpz]).replace(/\.0+$/, ''); break;
                    }
                    for (let j = i; j < Math.min(rows.length, i + 4); j++) { const m = hpMonth(hpRowTxt(rows[j])); if (m) { cur.month = m; const c0 = (rows[j] || []).map(hpS).find(z => hpMonth(z)) || hpRowTxt(rows[j]); cur.monthTxt = c0.replace(/^на\s*/i, '').replace(/\s+/g, ' ').trim(); break; } }
                    continue;
