                if (wc >= 0 && hpS(r[wc]) && !/^\d+$/.test(hpS(r[wc]))) cur.grp = hpS(r[wc]);
                const name = hpS(r[m]); if (!name || /^\d+$/.test(name) || /^(начальник|зам\.?|мастер|инженер|итого)/i.test(name)) continue;
