                if (ph >= 0) { const v = hpN(r[ph]); if (/итого|всего/i.test(t)) { out.total = { v: v !== null ? v : r.map(hpN).filter(x => x !== null).pop(), i: i, src: Object.assign({}, src, { r: i }) }; continue; } if (v !== null && hpS(r[1])) out.pos.push({ v: v, i: i }); }
