            if (typeof hpParseSpr === 'function') hpParseSpr = agmkExtend('hpParseSpr', 'v3.15: elektrovoz spravkasi', hpParseSpr, o => function (rows, src) { return elvIs(elvHead(rows, 16)) ? elvParseSpr(rows, src || {}) : o.apply(this, arguments); });
