                    let h = -1; for (let i = 0; i < Math.min(rows.length, 40); i++) { const rr = rows[i] || []; if (hpFind(rr, /наимен/) >= 0 && hpFind(rr, /вес/) >= 0) { h = i; break; } }
                    const cw = h >= 0 ? hpFind(rows[h], /с\s*уч[её]т/) : -1, c0 = h >= 0 ? hpFind(rows[h], /общий\s*вес/) : -1;
                    let cp = -1; if (h >= 0) (rows[h] || []).forEach((x, j) => { if (/^износ/.test(hpLow(x))) cp = j; });
                    r.items.forEach(x => { if (x.qty === null && x.w !== null && !/кг/i.test(x.unit)) x.w = null; }); // soni yozilmagan qator — vazn formulasi tekshirilmaydi
                    if (cw >= 0 && c0 >= 0 && cw !== c0) r.items.forEach(x => { const row = rows[x.i] || []; x.tot0 = hpN(row[c0]); const v = hpN(row[cw]); if (v !== null) x.tot = v; if (cp >= 0) x.p = hpN(row[cp]); });
