                    if (it.fakt !== null && it.price !== null && it.sum !== null && Math.abs(Math.round(it.fakt * it.price * 100) / 100 - it.sum) > Math.max(1, Math.abs(it.sum) * 0.0005)) add({ t: 'elvsum', lvl: 'red', sec: sec, name: it.name, msg: 'Miqdor × narx ≠ summa: ' + hpF(it.fakt) + ' × ' + hpF(it.price) + ' = ' + hpF(it.fakt * it.price) + ', yozilgan ' + hpF(it.sum) + '.', src: [it.src], diff: it.sum - it.fakt * it.price });
