                    if (set && it.plan !== null) { const r = nrmMatch(set, it.name, it.unit); if (r && r.it && r.lim !== null && it.plan > r.lim + 1e-9) add({ t: 'akt2nrm', lvl: 'blue', sec: sec, name: it.name, msg: 'Aktdagi «план расхода на 1 ед.» ' + hpF(it.plan) + ', tasdiqlangan norma (' + nrmLabel(set) + ') «' + r.it.name + '» — ' + hpF(r.lim) + ' ' + (it.unit || '') + '.', src: [it.src] }); }
